public class LabReport { private int reportId,patientId; private String testName,result,reportDate; public LabReport(int reportId,int patientId,String testName,String result,String reportDate){this.reportId=reportId;this.patientId=patientId;this.testName=testName;this.result=result;this.reportDate=reportDate;} public int getReportId(){return reportId;}public int getPatientId(){return patientId;}public String getTestName(){return testName;}public String getResult(){return result;}public String getReportDate(){return reportDate;} public void display(){System.out.println("Report ID : "+reportId);System.out.println("Patient ID: "+patientId);System.out.println("Test      : "+testName);System.out.println("Result    : "+result);System.out.println("Date      : "+reportDate);}}
